<?php
namespace Modules\BankingCoreDeposits\Http\Controllers;
use Illuminate\Http\Request; use Illuminate\Routing\Controller; use Modules\BankingCoreDeposits\Entities\DepositAccount; use Modules\BankingCoreDeposits\Entities\DepositProduct; use Modules\BankingCoreDeposits\Services\AccountNumberService; use Modules\BankingCoreDeposits\Services\DepositAccountService;
class AccountController extends Controller { public function index(){ $accounts=DepositAccount::latest()->paginate(25); return view('bankingcoredeposits::accounts.index',compact('accounts')); } public function create(){ $products=DepositProduct::where('is_active',1)->get(); return view('bankingcoredeposits::accounts.create',compact('products')); } public function store(Request $request, DepositAccountService $service, AccountNumberService $numbers){ $data=$request->all(); $data['account_no']=$data['account_no'] ?? $numbers->next($data['account_type'] ?? 'savings', $data['business_id'] ?? null); $service->open($data); return redirect()->route('banking.core-deposits.accounts.index')->with('status','Deposit account created'); } public function show(DepositAccount $account){ return view('bankingcoredeposits::accounts.show',compact('account')); } public function edit(DepositAccount $account){ return view('bankingcoredeposits::accounts.edit',compact('account')); } public function update(Request $request, DepositAccount $account){ $account->update($request->all()); return back()->with('status','Account updated'); } public function destroy(DepositAccount $account){ $account->delete(); return back(); } public function freeze(DepositAccount $account, DepositAccountService $service){ $service->changeStatus($account,'frozen','Frozen by user'); return back(); } public function unfreeze(DepositAccount $account, DepositAccountService $service){ $service->changeStatus($account,'active','Unfrozen by user'); return back(); } public function close(DepositAccount $account, DepositAccountService $service){ $service->changeStatus($account,'closed','Closed by user'); return back(); } public function reopen(DepositAccount $account, DepositAccountService $service){ $service->changeStatus($account,'active','Reopened by user'); return back(); } }
